import inspect
from itertools import groupby

def config_defaults():
    "Every key's built-in default, read from the module that owns it."
    from ramabana.core import AZURE_KEY_ENV, DEFAULT_POLICY, DFLT_IMAGE, DFLT_TURN, DFLT_VIDEO
    from ramabana.runtime import CLAUDE_EFFORT, EST_MARGIN, IMG_TOKENS, KEEP_RECENT, RESERVE
    d = {'learning': True, 'pane_close_done': True, 'calm': False, 'jobs.turn': DFLT_TURN, **{f'jobs.{j}': v or '' for j, v in DEFAULT_POLICY.items() if j != 'turn'},
         'window.margin': EST_MARGIN, 'window.image_tokens': IMG_TOKENS, 'window.reserve': RESERVE, 'window.keep_recent': KEEP_RECENT,
         'window.local_ctx': 0, 'compaction.auto': True, 'compaction.strategy': 'summary', 'runtime.effort': CLAUDE_EFFORT,
         'runtime.tool_channel': '', 'runtime.litert_backend': '', 'subagents.effort': '', 'subagents.tool_channel': '', 'azure.endpoint': '', 'azure.api_key_env': AZURE_KEY_ENV, 'jobs.image': DFLT_IMAGE, 'jobs.video': DFLT_VIDEO}
    try:
        from ramabana.cli import main
        ps = inspect.signature(getattr(main, '__wrapped__', main)).parameters
        d |= {k: ps[k[4:]].default for k in KEYS if k.startswith('cli.')}
    except Exception: pass   # without the cli extra there is no terminal session to set defaults for
    return d

CONFIG_HEAD = '''# Ramabana's settings for this machine. Every key is commented out, so each takes the default shown.
# Delete the leading '#' to set one. A command-line flag beats an env var, an env var beats this file,
# and this file beats the built-in default. Inside an app that embeds Ramabana, the env vars may carry
# that app's prefix too. `ramabana config show` prints what is in effect and where each value came from.
'''
MODEL_EXAMPLE = '''
# Corrections to the numbers fastllm's table gives one model, keyed by the name you choose it by
# (`/model NAME`) or its full vendor/model id. The name wins when both are set. A local model never
# runs past the window it was trained for.
# [model."openai/gpt-5.4"]
# max_input_tokens = 272000   # the input window each turn is sized against
# max_output_tokens = 32000   # tokens one reply may spend; unset, the model's own maximum (16000 if unknown)
# supports_images = true      # whether pictures may be sent to it

# A Claude Code turn that sends nothing for `timeout` seconds is ended and tried once more.
# [model."claude-opus-5-5"]
# timeout = 240               # raise it on a machine where Claude Code is slow to answer

# A table with `model_id` defines a model of its own under that name, for `[jobs]`, `--model` and `/model`.
# This one is an Azure OpenAI deployment on the v1 API; the key stays in the env var `api_key_env` names.
# [model."az-big"]
# model_id = "gpt-5.4"        # the deployment name
# base_url = "https://NAME.openai.azure.com/openai/v1"
# api_key_env = "AZURE_OPENAI_API_KEY"
# api_name = "openai"         # the Responses API; the default on an Azure host
# max_input_tokens = 272000
'''

def config_template():
    "A config.toml naming every key with its default, all commented out."
    d, out = config_defaults(), [CONFIG_HEAD]
    for table, rows in groupby(KEYS.items(), lambda kv: kv[0].rpartition('.')[0]):
        if table: out.append(f'[{table}]')
        for k, key in rows:
            beat = ' and '.join(x for x in (key.flag and f'the flag {key.flag}', key.env and f'${"" if key.plain else ENV_DEFAULT[0]}{key.env}') if x)
            out += [f'# {key.doc}' + (f'; {beat} beats it' if beat else ''), f'# {k.rpartition(".")[2]} = {_toml(d.get(k, ""))}']
        out.append('')
    return '\n'.join(out) + MODEL_EXAMPLE

def config_show(path=None):
    "Each setting in effect and where it came from: an env var, config.toml or the built-in default. A flag is per command line, so it is named, not read."
    p = Path(path).expanduser() if path else config_path()
    vals, bad = load_config(p)
    d = config_defaults()
    rows = [f'# {p}' + ('' if p.exists() else ' does not exist; `ramabana config init` writes one')]
    for k, key in KEYS.items():
        e = next((n for n in env_names(key) if os.environ.get(n)), None)
        v, src = (os.environ[e], f'${e}') if e else (vals[k], 'config.toml') if k in vals else (d.get(k, ''), 'built-in')
        rows.append(f'{k} = {_toml(v)}   # {src}' + (f'; {key.flag} beats it' if key.flag else ''))
    for name, o in vals.get('model', {}).items():
        for f, v in o.items():
            up = ''
            if f == 'max_input_tokens':
                try:
                    from ramabana.core import _spec_for
                    up = f', fastllm says {_spec_for(name).ctx:,}'
                except Exception: pass
            rows.append(f'model."{name}".{f} = {_toml(v)}   # config.toml{up}')
    return '\n'.join(rows + [f'warning: {b}' for b in bad])

CONFIG_USAGE = 'usage: ramabana config [show | init [--force] | path | set KEY VALUE | models]'

def _parsed(key, raw):
    "`raw`, as typed on a command line, in `key`'s type."
    t, s = key.type, str(raw).strip()
    if t is bool:
        if s.lower() not in ('true', 'false', 'on', 'off', 'yes', 'no', '1', '0'): return s
        return s.lower() in ('true', 'on', 'yes', '1')
    try:
        if t in (int, float): return t(s)
        if isinstance(t, tuple): return int(s) if s.isdigit() else s
    except ValueError: return s
    return [x.strip() for x in s.split(',') if x.strip()] if t is list else s

def config_set(key, raw, path=None):
    "Set one key from a command line: a `KEYS` name, or `model.NAME.key`, NAME quoted when it holds a dot. Returns the line written."
    if key.startswith('model.'):
        head, _, f = key.rpartition('.')
        name, k = head[len('model.'):].strip('"'), MODEL_KEYS.get(f)
        if not name or k is None: raise ValueError(_unknown(key, [f'model."{name}".{m}' for m in MODEL_KEYS]))
        table, shown = f'model.{json.dumps(name)}', f'model."{name}".{f}'
    elif (k := KEYS.get(key)) is None: raise ValueError(_unknown(key, KEYS))
    else: (table, _, f), shown = key.rpartition('.'), key
    if (why := _why(k, v := _parsed(k, raw))): raise ValueError(f'{shown} = {raw!r}: it must be {why}')
    set_table(table, {f: v}, path) if table else set_setting(key, v, path)
    if f == 'tool_channel' and v == 'native':
        from ramabana.core import forget_forced_tags
        forget_forced_tags()
    return f'{shown} = {_toml(v)}'
SETUP_USAGE = 'usage: ramabana setup [--provider P --name N --model-id M --endpoint URL --region R --key-env VAR --api-name A --jobs turn,summary]'

def config_cli(argv=()):
    "`ramabana config`: `show` what is in effect, `init` a commented config.toml, print its `path`, `set` one key, or list the `models`."
    a = list(argv); cmd = a[0] if a else 'show'
    p = config_path()
    if cmd == 'path': print(p); return 0
    if cmd == 'show': print(config_show(p)); return 0
    if cmd == 'models':
        from ramabana.core import models_table
        print(models_table()); return 0
    if cmd == 'set':
        if len(a) != 3: print(CONFIG_USAGE, file=sys.stderr); return 2
        try: print(f'{config_set(a[1], a[2], p)}   # in {p}'); return 0
        except ValueError as e: print(e, file=sys.stderr); return 1
    if cmd != 'init' or set(a[1:]) - {'--force'}: print(CONFIG_USAGE, file=sys.stderr); return 2
    if p.exists() and '--force' not in a:
        print(f'{p} exists; `ramabana config init --force` replaces it and keeps it as {p.name}.bak', file=sys.stderr)
        return 1
    print(config_reset(p))
    return 0

def config_reset(path=None):
    "Write the commented config.toml. Keep an existing file as `config.toml.bak` and preserve its `learning` setting. Return a status message."
    p = Path(path).expanduser() if path else config_path()
    old, bak = load_config(p)[0].get('learning'), p.exists()
    if bak: shutil.copy2(p, p.with_name(p.name + '.bak'))
    _locked_write(p, config_template())
    _LOADED.pop(p, None)
    if old is not None: set_setting('learning', old, p)
    return f'wrote {p}' + (f'; the old one is {p.name}.bak' if bak else '')

HISTORY_USAGE = 'usage: ramabana history compact [--cfg DIR] [--name NAME] [--force] [--no-backup]'

def history_cli(argv=()):
    "`ramabana history compact`: rewrite the turn log once. Old pictures and long tool results stop filling it."
    a = list(argv)
    if a[:1] != ['compact']: print(HISTORY_USAGE, file=sys.stderr); return 2
    import argparse
    p = argparse.ArgumentParser(prog='ramabana history compact')
    p.add_argument('--cfg', default='~/.config/ramabana', help='the config folder holding the log')
    p.add_argument('--name', default='agent', help='the history name')
    p.add_argument('--force', action='store_true', help='go on although another live process holds a session')
    p.add_argument('--no-backup', action='store_true', help='keep no .pre-compact copy of the log and index')
    f = p.parse_args(a[1:])
    from ramabana.agent import HistoryBusy, compact_history
    try: got = compact_history(f.cfg, f.name, backup=not f.no_backup, force=f.force)
    except (HistoryBusy, FileExistsError, FileNotFoundError) as e: print(e, file=sys.stderr); return 1
    mb = lambda n: f'{n / 1e6:,.1f} MB'
    print(f"{f.name}-history.jsonl: {mb(got['before'])} → {mb(got['after'])}; {got['rewritten']} of {got['rows']} rows rewritten, {got['images']} pictures, {got['results']} results moved to {f.name}-details/")
    return 0


